package ug.fuggieprints.app;
import android.app.*;import android.content.*;import android.os.Build;import java.util.*;
public class ReminderReceiver extends BroadcastReceiver {
 public static final int[] HOURS={9,13,17};public static final String CHANNEL="daily-studio-updates";public static void createChannel(Context c){NotificationManager m=(NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE);NotificationChannel channel=new NotificationChannel(CHANNEL,"Fuggie Prints daily reminders",NotificationManager.IMPORTANCE_DEFAULT);channel.setDescription("Three daily studio reminders, around 9 AM, 1 PM and 5 PM Uganda time. Manage in phone settings.");m.createNotificationChannel(channel);}
 public static void scheduleAll(Context c){for(int slot=0;slot<3;slot++)schedule(c,slot);}static void schedule(Context c,int slot){Calendar next=Calendar.getInstance(TimeZone.getTimeZone("Africa/Kampala"));next.set(Calendar.HOUR_OF_DAY,HOURS[slot]);next.set(Calendar.MINUTE,0);next.set(Calendar.SECOND,0);next.set(Calendar.MILLISECOND,0);if(next.getTimeInMillis()<=System.currentTimeMillis())next.add(Calendar.DAY_OF_MONTH,1);Intent i=new Intent(c,ReminderReceiver.class).putExtra("slot",slot);PendingIntent p=PendingIntent.getBroadcast(c,100+slot,i,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);((AlarmManager)c.getSystemService(Context.ALARM_SERVICE)).setAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,next.getTimeInMillis(),p);}
 @Override public void onReceive(Context c,Intent i){int slot=i.getIntExtra("slot",0);if(slot<0||slot>2)return;try{createChannel(c);String key=Calendar.getInstance(TimeZone.getTimeZone("Africa/Kampala")).get(Calendar.YEAR)+"-"+Calendar.getInstance(TimeZone.getTimeZone("Africa/Kampala")).get(Calendar.DAY_OF_YEAR);android.content.SharedPreferences prefs=c.getSharedPreferences("reminders",0);if(!key.equals(prefs.getString("last-"+slot,""))){NotificationManager m=(NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE);if(m.areNotificationsEnabled()){String[] text={"Have a printing project in mind? Request a quote from Fuggie Prints.","Printing, branding and online services — explore what we can create for you.","Discover Fuggie Prints videos and plan your next project."};PendingIntent open=PendingIntent.getActivity(c,0,new Intent(c,MainActivity.class),PendingIntent.FLAG_IMMUTABLE|PendingIntent.FLAG_UPDATE_CURRENT);m.notify(200+slot,new Notification.Builder(c,CHANNEL).setSmallIcon(R.drawable.notification_icon).setContentTitle("Fuggie Prints Media").setContentText(text[slot]).setStyle(new Notification.BigTextStyle().bigText(text[slot])).setContentIntent(open).setAutoCancel(true).build());prefs.edit().putString("last-"+slot,key).apply();}}}finally{schedule(c,slot);}}
}
